  "glossary": [
    {
      "term": "MSSR",
      "zh": "身教式持續安靜閱讀（Modeled Sustained Silent Reading）：老師和學生在同一段時間各自安靜閱讀，用身教帶出閱讀習慣。"
    },
    {
      "term": "柴窯",
      "zh": "用木柴當燃料燒製陶瓷的窯，燒製時間長，柴灰落在作品上會形成自然釉色。"
    },
    {
      "term": "九降風",
      "zh": "新竹秋冬強勁乾燥的東北季風，最適合曝曬烏魚子、米粉與柿餅。"
    },
    {
      "term": "樂樂棒球",
      "zh": "把球放在打擊座上打擊的簡化棒球，人人都能擊中、適合國小學生。"
    },
    {
      "term": "基層運動選手訓練站",
      "zh": "教育部體育署補助各縣市學校設立的選手培訓點，大庄為新竹市射箭項目訓練站。"
    },
    {
      "term": "碳盤查",
      "zh": "把生活或活動中各種排放換算成二氧化碳當量，找出可以減碳的地方。"
    },
    {
      "term": "食魚教育",
      "zh": "認識魚的種類、構造、漁業文化與永續海鮮選擇的教育。"
    }
  ],
